mapper.select:

SELECT
    user_id,
    rank_no,
    nickname,
    score,
    completed_at
FROM ranked

    WHERE score < #{cursorScore}
       OR (
           score = #{cursorScore}
           AND completed_at > #{cursorCompletedAt}
       )
       OR (
           score = #{cursorScore}
           AND completed_at = #{cursorCompletedAt}
           AND user_id > #{cursorUserId}
       )

ORDER BY score DESC, completed_at ASC, user_id ASC
LIMIT #{limit}
